"% Steady level-flight trim for a transport aircraft
% Trim conditions: L = W, T = D
% Solve for alpha and required thrust

W       = 175000.0;   % weight (lbf)
S       = 2050.0;     % wing area (ft^2)
h       = 26000.0;    % altitude (ft)
V       = 690.0;      % true airspeed (ft/s)

% Aerodynamic coefficients
CL0     = 0.12;       % lift at zero alpha
CLalpha = 4.9;        % lift curve slope (1/rad)
CD0     = 0.023;      % zero-lift drag coefficient
k       = 0.041;      % induced drag factor

% Atmosphere
rho0   = 0.0023769;   % sea-level density (slug/ft^3)
Hscale = 23800.0;     % scale height (ft)

% Engine
T0 = 54000.0;         % reference thrust (lbf)
V0 = 690.0;           % reference speed (ft/s)

% --- Atmosphere and dynamic pressure ---
rho  = rho0 * exp(-h / Hscale);
qbar = 0.5 * rho * V^2;

% --- Trim lift coefficient and angle of attack ---
% L = qbar * S * CL = W  ->  CL = W/(qbar*S)
CL_trim   = W / (qbar * S);
alpha_rad = (CL_trim - CL0) / CLalpha;
alpha_deg = alpha_rad * 180.0 / pi;

% --- Trim drag and required thrust ---
% D = qbar * S * CD,  with CD = CD0 + k * CL^2
CD_trim = CD0 + k * CL_trim^2;
D_trim  = qbar * S * CD_trim;

% Steady level flight: thrust equals drag
T_required = D_trim;

% --- Build result struct and write JSON ---
result = struct();
result.alpha_trim_deg = alpha_deg;
result.thrust_lbf     = T_required;

json_text = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_text);
fclose(fid);"
